import {coverage,signedOutFixture} from './coverage.mjs';
import {installThemeAdapter} from '../theme-adapter.mjs';
import {createFixtureTransport,fixtureIds,sampleText} from './fixtures.mjs';
const id=new URLSearchParams(location.search).get('fixture')||'studio-empty';
if(!fixtureIds.includes(id))throw Error('Unknown Reads fixture.');
// Install before production modules. No server/account/provider is imported.
globalThis.__readsFixtureFetch=createFixtureTransport(id);
globalThis.__readsSyntheticRecording = new File([Uint8Array.from(atob(""),c=>c.charCodeAt(0))],'synthetic-tone.wav',{type:'audio/wav'});
await import('../app.js');
const banner=document.createElement('p');banner.className='design-fixture-notice';banner.textContent="Synthetic design preview. No account, backend, provider, or live waiting list is connected. Nothing is saved or sent.";document.body.prepend(banner);
document.querySelectorAll('.wordmark,#header-login,#login').forEach(link=>{link.href='/design-system/previews/reads/fixture/?fixture='+(['landing','waitlist'].includes(id)?'studio-empty':'landing');});
document.getElementById('logout').onclick=()=>location.assign('/design-system/previews/reads/fixture/?fixture=landing');
if(id==='waitlist'||id.startsWith('waitlist-'))document.getElementById('waitlist').click();
if(id==='voice-sample')document.getElementById('voice-details').open=true;
if(id==='hosted-consent'){const field=document.getElementById('text');field.value=sampleText;field.dispatchEvent(new Event('input'));}
const scenario=coverage[id];
if(scenario?.region==='voice')document.getElementById('voice-details').open=true;
if(scenario?.region==='reader'&&id!=='reader-empty') {
  const field=document.getElementById('text');field.value=id==='reader-long'?sampleText.repeat(100):sampleText;field.dispatchEvent(new Event('input'));
  document.querySelector('#reader details').open=true;
}
if(scenario?.region){
  // Hide siblings, never copy or replace production elements. Keep hidden handlers intact.
  const style=document.createElement('style');
  style.textContent='body>header,main>.intro,body>footer,#studio>.notice,#studio>#message{display:none!important}main{padding-top:24px!important}.workspace{grid-template-columns:minmax(0,1fr)!important}'+({reader:'.workspace>aside,.library{display:none!important}',voice:'.workspace>section,.library,.small-note{display:none!important}',jobs:'.workspace{display:none!important}'}[scenario.region]);document.head.append(style);
}
// Flush production promise continuations without waiting for offscreen iframe animation frames.
await new Promise(resolve=>setTimeout(resolve,0));
document.documentElement.dataset.fixtureReady=id;
const disposeTheme=installThemeAdapter(theme=>{document.documentElement.dataset.theme=theme;if(getComputedStyle(document.documentElement).getPropertyValue('--ds-color-background').trim()!=='#1d1b1a')throw Error('Reads palette unavailable');},{themes:['dark']});
addEventListener('pagehide',disposeTheme,{once:true});

// No user file is read: recording fixtures display only the generated sample.
const sampleInput=document.getElementById('sample');
if(id.startsWith('recording-')){
 const files=new DataTransfer();files.items.add(globalThis.__readsSyntheticRecording);sampleInput.files=files.files;
 sampleInput.dispatchEvent(new Event('change'));
}
// Opaque frames deliberately lack allow-forms. Keep real handlers but invoke them
// with a local event; the observer also handles hosted voice forms added on rerender.
function adaptForms(){for (const form of document.forms) {
 if(form.dataset.previewAdapted)continue;

 const submit = [...form.querySelectorAll('button')].find(button => button.type === 'submit');
 if (!submit || !form.onsubmit) continue;
 form.dataset.previewAdapted='true';
 submit.dataset.previewSubmit='true';
 submit.type = 'button';
 submit.onclick = event => { event.preventDefault(); if (form.reportValidity()) form.onsubmit(event); };
 form.addEventListener('keydown', event => { if (event.key === 'Enter' && event.target.matches('input:not([type=file])')) { event.preventDefault(); if (!submit.disabled) submit.click(); } });
}}
adaptForms();new MutationObserver(adaptForms).observe(document.body,{childList:true,subtree:true});
